class SporadicTask:
    def __init__(self, C_i, D_i, T_i):
        self.C = C_i
        self.D = D_i
        self.T = T_i
        assert self.D <= self.T, "Deadline must be less than or equal to period"

def calculate_task_parameters(task_set):
    for task_i in task_set:
        task_i.S = task_i.D - task_i.C
        task_i.U = task_i.C / task_i.T

    U_tau = sum(task.U for task in task_set)
    return U_tau

class TaskInstance:
    def __init__(self, task_ref, release_time):
        self.task = task_ref
        self.r = release_time
        self.d = self.r + self.task.D
        self.l = self.d - self.task.C

class SporadicTask:
