        self.priority = priority

def has_higher_priority(task_i, task_j):
    return task_i.priority > task_j.priority

def calculate_bar_edf_np_params(task_set):
    C_max = max(task.C for task in task_set)
    D_min = min(task.D for task in task_set)

    V_values = []
    for task_i in task_set:
        if task_i.D > C_max:
            V_i = task_i.C / (task_i.D - C_max)
        else:
            V_i = float('inf') # Represents infinity
        V_values.append(V_i)

    V_sum_tau = sum(V_values)
    V_max_tau = max(V_values)

    return C_max, D_min, V_sum_tau, V_max_tau

def calculate_I_3_1_tau_i(A_k, S_k, T_i, C_i):
    num_full_instances = (A_k + S_k) // T_i
    remainder_time = (A_k + S_k) % T_i
    return num_full_instances * C_i + min(C_i, remainder_time)

def calculate_I_1_EDF_np_tau_i(task_i, task_k, A_k):
    D_i = task_i.D
    D_k = task_k.D
    T_i = task_i.T
    C_i = task_i.C
    S_k = task_k.S

    if D_i > D_k and A_k == 0:
        return 0
    elif task_i == task_k:
        return calculate_I_1_1_tau_k(A_k, T_i, C_i)
    else:
        alpha_1 = calculate_alpha_1(A_k, S_k, T_i, D_i)
        alpha_2 = calculate_alpha_2(A_k, S_k, T_i)

        if (D_i <= D_k and alpha_1 > A_k + D_k) or \
           (D_i > D_k and alpha_2 >= A_k and A_k > 0):
            return calculate_I_2_1_tau_i(A_k, S_k, T_i, C_i)
        else:
            return calculate_I_3_1_tau_i(A_k, S_k, T_i, C_i)

def calculate_I_2_2_tau_i(A_k, D_k, T_i, C_i):
    total_length = A_k + D_k
    num_full_instances = total_length // T_i
    remainder_time = total_length % T_i
    return num_full_instances * C_i + min(C_i, remainder_time)

def calculate_I_3_2_tau_i(task_i, task_k, A_k):
    C_i = task_i.C
    T_i = task_i.T
    D_i = task_i.D

    if A_k == 0:
        return C_i - 1 # Specific edge case from paper
    else:
        num_full_instances = ((A_k - 1) // T_i) + 1
        upsilon_val = calculate_upsilon(C_i, A_k, T_i, D_i)
        return num_full_instances * C_i + upsilon_val

def calculate_I_2_EDF_np_tau_i(task_i, task_k, A_k):
    D_i = task_i.D
    D_k = task_k.D
    S_i = task_i.S
    S_k = task_k.S
    C_i = task_i.C
    C_k = task_k.C
    T_i = task_i.T

    if task_i == task_k:
        return calculate_I_1_2_tau_k(A_k, D_k, T_i, C_i)
    elif D_i <= D_k and S_i > C_k:
        return calculate_I_2_2_tau_i(A_k, D_k, T_i, C_i)
    elif D_i > D_k and S_k >= C_i:
        return calculate_I_3_2_tau_i(task_i, task_k, A_k)
    else:
        return calculate_I_4_2_tau_i(task_i, task_k, A_k)

def calculate_I_1_FP_np_tau_i(task_i, task_k, A_k):
    P_i = task_i.priority
    P_k = task_k.priority
    T_i = task_i.T
    C_i = task_i.C
    S_k = task_k.S

    if P_i < P_k and A_k == 0:
        return 0
    elif task_i == task_k:
        return calculate_I_1_1_tau_k(A_k, T_i, C_i)
    else:
        alpha_2 = calculate_alpha_2(A_k, S_k, T_i)

        if P_i < P_k and alpha_2 >= A_k and A_k > 0:
            # Note: The original paper refers to I_2_1_tau_i here, which is based on D_i <= D_k.
            # For FP, this condition is replaced by priority. The underlying calculation (body instances only) is the same.
            return calculate_I_2_1_tau_i(A_k, S_k, T_i, C_i) # Reusing the calculation logic
        else:
            return calculate_I_3_1_tau_i(A_k, S_k, T_i, C_i)

def calculate_I_2_FP_np_tau_i(task_i, task_k, A_k):
    P_i = task_i.priority
    P_k = task_k.priority
    S_k = task_k.S
    C_i = task_i.C
    D_k = task_k.D
    T_i = task_i.T
    D_i = task_i.D

    if task_i == task_k:
        return calculate_I_1_2_tau_k(A_k, D_k, T_i, C_i)
    elif P_i < P_k and S_k >= C_i:
        # Note: The original paper refers to I_3_2_tau_i here, which is based on D_i > D_k.
        # For FP, this condition is replaced by priority. The underlying calculation is the same.
        return calculate_I_3_2_tau_i(task_i, task_k, A_k) # Reusing the calculation logic
    else:
        return calculate_I_4_2_tau_i(task_i, task_k, A_k)
